<?php // Mobile app shell: top bar + floating tab bar with a big red SOS button in the middle. Needs config.php first.
function active_trip($uid){return q("SELECT t.id trip_id,t.depart_time,b.reg_number reg,b.operator,b.operator_id,b.driver_name,o.phone op_phone FROM bookings k JOIN trips t ON t.id=k.trip_id JOIN buses b ON b.id=t.bus_id LEFT JOIN users o ON o.id=b.operator_id WHERE k.user_id=? AND k.status='confirmed' AND t.depart_date=CURDATE() AND t.status NOT IN('cancelled','completed') ORDER BY ABS(TIME_TO_SEC(TIMEDIFF(t.depart_time,CURTIME()))) LIMIT 1",[$uid])->fetch()?:null;}
function ic($n,$s=24){static $p=['bus'=>'<rect x="4" y="3" width="16" height="15" rx="3"/><path d="M4 11h16M8 21v-3M16 21v-3"/><circle cx="8.5" cy="14.5" r=".7"/><circle cx="15.5" cy="14.5" r=".7"/>','pin'=>'<path d="M12 21s7-6.2 7-11a7 7 0 0 0-14 0c0 4.8 7 11 7 11z"/><circle cx="12" cy="10" r="2.5"/>','map'=>'<path d="M9 4 3 6v14l6-2 6 2 6-2V4l-6 2-6-2zM9 4v14M15 6v14"/>','stop'=>'<path d="M12 3v18"/><path d="M6 5h10l2 3-2 3H6z"/>','ticket'=>'<path d="M3 9V6h18v3a3 3 0 0 0 0 6v3H3v-3a3 3 0 0 0 0-6z"/><path d="M14 6v12" stroke-dasharray="2 2"/>','card'=>'<rect x="3" y="5" width="18" height="14" rx="2.5"/><path d="M3 10h18M7 15h4"/>','cone'=>'<path d="M12 3 6.5 19h11zM8.8 13h6.4M10.2 8h3.6M4 21h16"/>','users'=>'<circle cx="9" cy="8" r="3"/><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6"/><circle cx="17" cy="9" r="2.3"/><path d="M16 14.2c2.9.2 5 2.5 5 5.8"/>','home'=>'<path d="M4 11 12 4l8 7v9H4z"/><path d="M10 20v-6h4v6"/>','user'=>'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7"/>','bell'=>'<path d="M6 17v-6a6 6 0 0 1 12 0v6l2 2H4zM10 21h4"/>','shield'=>'<path d="M12 3 5 6v6c0 4.5 3 7.5 7 9 4-1.5 7-4.5 7-9V6z"/><path d="m9 12 2 2 4-4"/>','phone'=>'<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z"/>','msg'=>'<path d="M4 5h16v11H9l-5 4z"/>','video'=>'<rect x="3" y="6" width="13" height="12" rx="2.5"/><path d="m16 11 5-3v8l-5-3z"/>','mic'=>'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/>','share'=>'<circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="6" r="2.5"/><circle cx="18" cy="18" r="2.5"/><path d="m8.2 10.8 7.6-3.6M8.2 13.2l7.6 3.6"/>','compass'=>'<circle cx="12" cy="12" r="9"/><path d="m15.5 8.5-2 5-5 2 2-5z"/>','chev'=>'<path d="m9 6 6 6-6 6"/>','search'=>'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>','plus'=>'<path d="M12 5v14M5 12h14"/>'];
 return '<svg class="ic" width="'.$s.'" height="'.$s.'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($p[$n]??'').'</svg>';}
function app_head($t){?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title><?=e($t)?> · Ride Track</title>
