<style>
body.appbody{--bg:#F4F7F4;--pri:#0F4C3A;--dk:#10261E;--ln:#D9E3DC;--mut:#5B7066;--c1:#E3EDE6;--c2:#CFE0D5;--c3:#0F4C3A;--sh:rgba(16,38,30,.10);--inp:#fff;--sos:#D8212F;
 margin:0;background:var(--bg);color:var(--dk);font:17px/1.55 'Hind Siliguri',system-ui,sans-serif;padding-bottom:calc(112px + env(safe-area-inset-bottom))}
.appbody h1,.appbody h2,.appbody h3,.appbody .logo{font-family:'Barlow Semi Condensed','Hind Siliguri',sans-serif;letter-spacing:.01em}
