.apptop{display:flex;align-items:center;justify-content:space-between;padding:calc(14px + env(safe-area-inset-top)) 18px 6px;max-width:520px;margin:0 auto}
.apptop .logo{font-size:1.65rem;font-weight:700;color:var(--dk);text-decoration:none}.apptop .logo span{color:var(--pri)}
.apptop .bell{display:grid;place-items:center;width:44px;height:44px;border-radius:50%;background:#fff;border:1px solid var(--ln);color:var(--dk)}
.appwrap{max-width:520px;margin:0 auto;padding:0 18px 20px}.appwrap h2{font-size:2rem;font-weight:700;margin:.2em 0 .1em;line-height:1.1}.appwrap h3{font-size:1.2rem;font-weight:700;margin:0 0 .5em}
.where{display:flex;align-items:center;gap:12px;background:#fff;border:1.5px solid var(--dk);border-radius:20px;padding:16px 18px;margin:16px 0;text-decoration:none;color:var(--dk);font-weight:600;font-size:1.1rem;box-shadow:0 6px 0 var(--dk)}
.where small{display:block;font-weight:400;color:var(--mut);font-size:.88rem}.where .ic{color:var(--pri);flex:none}
.stub{position:relative;background:var(--pri);color:#fff;border-radius:22px;padding:18px 20px;margin:16px 0;-webkit-mask:radial-gradient(circle 11px at 0 62%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 11px at 100% 62%,#0000 98%,#000) right/51% 100% no-repeat;mask:radial-gradient(circle 11px at 0 62%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 11px at 100% 62%,#0000 98%,#000) right/51% 100% no-repeat}
.stub .tm{font:700 2.6rem/1 'Barlow Semi Condensed',sans-serif}.stub .sm{opacity:.85;font-size:.95rem}.stub .lbl{font-size:.85rem;opacity:.8}
.stub .acts{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px;padding-top:14px;border-top:2px dashed rgba(255,255,255,.35)}.stub .acts a{display:flex;align-items:center;justify-content:center;gap:8px;padding:12px;border-radius:14px;background:#fff;color:var(--pri);font-weight:700;text-decoration:none}
.qa{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:14px 0}
.qa a{background:var(--c1);border-radius:22px;padding:18px 16px;text-decoration:none;color:var(--dk);font-weight:700;min-height:112px;display:flex;flex-direction:column;justify-content:space-between;gap:14px}
.qa a:nth-child(3n+1){background:#fff;border:1px solid var(--ln)}.qa .ic{color:var(--pri)}.qa small{display:block;color:var(--mut);font-weight:400;font-size:.85rem;line-height:1.2}
.abanner{display:flex;gap:12px;align-items:flex-start;background:#FFF4DB;border-radius:18px;padding:14px 16px;margin:14px 0;color:#5C4210}.abanner a{color:#5C4210;font-weight:700}.abanner .ic{flex:none;margin-top:2px}
.acard,.grp{background:#fff;border:1px solid var(--ln);border-radius:22px;padding:18px;margin:14px 0}
.abtn{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;padding:16px;border-radius:18px;border:0;background:var(--pri);color:#fff;font:700 1.05rem 'Hind Siliguri',sans-serif;text-decoration:none;cursor:pointer;min-height:56px}
.abtn.red{background:var(--sos)}.abtn.ghost{background:transparent;color:var(--pri);border:1.5px solid var(--pri)}.abtn:focus-visible,.where:focus-visible,.tab:focus-visible,.qa a:focus-visible{outline:3px solid #E9B44C;outline-offset:2px}
.arow{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}.arow a{padding:12px 4px;border-radius:14px;background:var(--c1);text-align:center;text-decoration:none;font-weight:600;font-size:.9rem;color:var(--dk)}
.tabbar{position:fixed;left:50%;transform:translateX(-50%);width:calc(100% - 24px);max-width:496px;bottom:calc(12px + env(safe-area-inset-bottom));background:#fff;border:1px solid var(--ln);border-radius:28px;display:grid;grid-template-columns:repeat(5,1fr);padding:8px 6px;z-index:30;box-shadow:0 10px 30px rgba(16,38,30,.18)}
.tab{display:flex;flex-direction:column;align-items:center;gap:2px;text-decoration:none;color:var(--mut);font-size:.74rem;font-weight:600;padding:6px 0;border-radius:16px}.tab.on{color:var(--pri);background:var(--c1)}
.sostab{position:relative;background:none!important}.sostab b{position:relative;display:grid;place-items:center;width:68px;height:68px;margin:-34px auto 0;border-radius:50%;background:radial-gradient(circle at 32% 26%,#F0505C,#C0182A);color:#fff;font:700 1.15rem 'Barlow Semi Condensed',sans-serif;letter-spacing:.04em;border:4px solid #fff;box-shadow:0 8px 18px rgba(216,33,47,.5)}
.sostab b::after{content:"";position:absolute;inset:-10px;border-radius:50%;border:2px solid var(--sos);opacity:0;animation:sosping 2.8s ease-out infinite}.sostab span{color:var(--sos);font-weight:700}
@keyframes sosping{0%{transform:scale(.8);opacity:.55}70%,100%{transform:scale(1.25);opacity:0}}
@media (prefers-reduced-motion:reduce){.sostab b::after{animation:none}}
</style></head><body class="appbody"><div class="apptop"><a class="logo" href="app.php">Ride<span>Track</span></a><a class="bell" href="notifications.php" aria-label="Alerts"><?=ic('bell',22)?></a></div><div class="appwrap">
