<nav class="tabbar" aria-label="App menu"><?php foreach($t as $k=>$v){if($k=='sos'){echo '<a class="tab sostab" href="'.$v[0].'" aria-label="Emergency SOS"><b>SOS</b><span>'.$v[2].'</span></a>';}else echo '<a class="tab'.($on==$k?' on':'').'" href="'.$v[0].'">'.ic($v[1],24).$v[2].'</a>';}?></nav>
